    //=============================================================================
// Module: alu
// Description: 32-bit ALU with registered outputs.
//   Performs ADD, SUB, AND, OR, XOR, SLL, SRL, SRA, SLT, SLTU.
//   Outputs are registered on the rising clock edge.
//   Flags: zero (registered result == 0), overflow (signed ADD/SUB only),
//          negative (MSB of registered result).
//   Shift amounts use the low 5 bits of operand B (0..31).
//   Unused opcodes (1010..1111) force result = 0, zero = 1, overflow = 0.
//=============================================================================
module alu (
    input  wire        clk,
    input  wire        rst,
    input  wire [31:0] a,
    input  wire [31:0] b,
    input  wire [3:0]  opcode,
    output reg  [31:0] result,
    output reg         zero,
    output reg         overflow,
    output reg         negative
);

    //------------------------------------------------------------------
    // Combinational result/flag computation
    //------------------------------------------------------------------
    reg        [31:0] temp_result;
    reg               temp_overflow;

    // Scratch registers used by the unrolled barrel shifters.
    // Only one opcode branch is active per evaluation, so they may be
    // shared between the SLL / SRL / SRA branches.
    reg        [31:0] shift_tmp;
    reg signed [31:0] arith_tmp;   // signed view used for SRA (>>>)

    always @(*) begin
        // Safe defaults so every branch fully assigns both signals
        temp_result   = 32'h00000000;
        temp_overflow = 1'b0;
        shift_tmp     = 32'h00000000;
        arith_tmp     = 32'sd0;

        case (opcode)
            //----------------------------------------------------------
            4'b0000: begin // ADD : (A + B) modulo 2^32
                temp_result = a + b;
                // Signed overflow: same-sign operands, result sign differs
                temp_overflow = (a[31] & b[31] & ~temp_result[31]) |
                                (~a[31] & ~b[31] & temp_result[31]);
            end

            //----------------------------------------------------------
            4'b0001: begin // SUB : (A - B) modulo 2^32
                temp_result = a - b;
                // Signed overflow: opposite-sign operands, result sign
                // differs from the minuend sign
                temp_overflow = (a[31] & ~b[31] & ~temp_result[31]) |
                                (~a[31] & b[31] & temp_result[31]);
            end

            //----------------------------------------------------------
            4'b0010: begin // AND : bitwise A & B
                temp_result = a & b;
            end

            //----------------------------------------------------------
            4'b0011: begin // OR : bitwise A | B
                temp_result = a | b;
            end

            //----------------------------------------------------------
            4'b0100: begin // XOR : bitwise A ^ B
                temp_result = a ^ b;
            end

            //----------------------------------------------------------
            4'b0101: begin // SLL : logical left shift, amount = B[4:0]
                // Unrolled barrel shifter (constant shift amounts only)
                shift_tmp = a;
                if (b[0]) shift_tmp = shift_tmp << 1;
                if (b[1]) shift_tmp = shift_tmp << 2;
                if (b[2]) shift_tmp = shift_tmp << 4;
                if (b[3]) shift_tmp = shift_tmp << 8;
                if (b[4]) shift_tmp = shift_tmp << 16;
                temp_result = shift_tmp;
            end

            //----------------------------------------------------------
            4'b0110: begin // SRL : logical right shift, zero filled
                // Unrolled barrel shifter (constant shift amounts only)
                shift_tmp = a;
                if (b[0]) shift_tmp = shift_tmp >> 1;
                if (b[1]) shift_tmp = shift_tmp >> 2;
                if (b[2]) shift_tmp = shift_tmp >> 4;
                if (b[3]) shift_tmp = shift_tmp >> 8;
                if (b[4]) shift_tmp = shift_tmp >> 16;
                temp_result = shift_tmp;
            end

            //----------------------------------------------------------
            4'b0111: begin // SRA : arithmetic right shift, sign extended
                // arith_tmp is a signed reg, so >>> performs the
                // sign-extending arithmetic shift.
                arith_tmp = a;
                if (b[0]) arith_tmp = arith_tmp >>> 1;
                if (b[1]) arith_tmp = arith_tmp >>> 2;
                if (b[2]) arith_tmp = arith_tmp >>> 4;
                if (b[3]) arith_tmp = arith_tmp >>> 8;
                if (b[4]) arith_tmp = arith_tmp >>> 16;
                temp_result = arith_tmp;
            end

            //----------------------------------------------------------
            4'b1000: begin // SLT : signed set-less-than -> 1 / 0
                temp_result = ($signed(a) < $signed(b)) ? 32'h00000001
                                                        : 32'h00000000;
            end

            //----------------------------------------------------------
            4'b1001: begin // SLTU : unsigned set-less-than -> 1 / 0
                temp_result = (a < b) ? 32'h00000001 : 32'h00000000;
            end

            //----------------------------------------------------------
            default: begin // 1010..1111 : unused -> result 0, overflow 0
                temp_result   = 32'h00000000;
                temp_overflow = 1'b0;
            end
        endcase
    end

    //------------------------------------------------------------------
    // Sequential output registers (active-high synchronous reset)
    //------------------------------------------------------------------
    always @(posedge clk) begin
        if (rst) begin
            result   <= 32'h00000000;
            zero     <= 1'b0;
            overflow <= 1'b0;
            negative <= 1'b0;
        end else begin
            result   <= temp_result;
            zero     <= (temp_result == 32'h00000000);
            overflow <= temp_overflow;
            negative <= temp_result[31];
        end
    end

endmodule